CREATE TABLE IF NOT EXISTS c_automations (_id TEXT PRIMARY KEY NOT NULL, accountId TEXT, data TEXT NOT NULL);
CREATE INDEX IF NOT EXISTS i_automations__accountId ON c_automations (accountId);
CREATE INDEX IF NOT EXISTS i_automations__newsletterId__createdAt_d ON c_automations (json_extract(data, '$.newsletterId') ASC, json_extract(data, '$.createdAt') DESC);
CREATE INDEX IF NOT EXISTS i_automations__status ON c_automations (json_extract(data, '$.status') ASC);
CREATE TABLE IF NOT EXISTS c_automationenrollments (_id TEXT PRIMARY KEY NOT NULL, accountId TEXT, data TEXT NOT NULL);
CREATE INDEX IF NOT EXISTS i_automationenrollments__accountId ON c_automationenrollments (accountId);
CREATE UNIQUE INDEX IF NOT EXISTS u_automationenrollments__automationId__contactId__cycle ON c_automationenrollments (json_extract(data, '$.automationId') ASC, json_extract(data, '$.contactId') ASC, IFNULL(json_extract(data, '$.cycle'), '') ASC);
CREATE INDEX IF NOT EXISTS i_automationenrollments__nextRunAt ON c_automationenrollments (json_extract(data, '$.nextRunAt') ASC) WHERE json_extract(data, '$.nextRunAt') IS NOT NULL;
CREATE INDEX IF NOT EXISTS i_automationenrollments__automationId__status ON c_automationenrollments (json_extract(data, '$.automationId') ASC, json_extract(data, '$.status') ASC);
CREATE INDEX IF NOT EXISTS i_automationenrollments__contactId ON c_automationenrollments (json_extract(data, '$.contactId') ASC);
CREATE TABLE IF NOT EXISTS c_customfields (_id TEXT PRIMARY KEY NOT NULL, accountId TEXT, data TEXT NOT NULL);
CREATE INDEX IF NOT EXISTS i_customfields__accountId ON c_customfields (accountId);
CREATE UNIQUE INDEX IF NOT EXISTS u_customfields__newsletterId__key ON c_customfields (json_extract(data, '$.newsletterId') ASC, json_extract(data, '$.key') ASC);
CREATE UNIQUE INDEX IF NOT EXISTS u_messages__enrollmentId__stepId ON c_messages (json_extract(data, '$.enrollmentId') ASC, json_extract(data, '$.stepId') ASC) WHERE json_extract(data, '$.kind') = 'automation';
CREATE INDEX IF NOT EXISTS i_messages__automationId ON c_messages (json_extract(data, '$.automationId') ASC) WHERE json_extract(data, '$.automationId') IS NOT NULL;
CREATE TABLE IF NOT EXISTS c_segments (_id TEXT PRIMARY KEY NOT NULL, accountId TEXT, data TEXT NOT NULL);
CREATE INDEX IF NOT EXISTS i_segments__accountId ON c_segments (accountId);
CREATE UNIQUE INDEX IF NOT EXISTS u_segments__newsletterId__name ON c_segments (json_extract(data, '$.newsletterId') ASC, json_extract(data, '$.name') ASC);
CREATE TABLE IF NOT EXISTS c_tags (_id TEXT PRIMARY KEY NOT NULL, accountId TEXT, data TEXT NOT NULL);
CREATE INDEX IF NOT EXISTS i_tags__accountId ON c_tags (accountId);
CREATE UNIQUE INDEX IF NOT EXISTS u_tags__newsletterId__name ON c_tags (json_extract(data, '$.newsletterId') ASC, json_extract(data, '$.name') ASC);
